package com.hbm.satellite.cargo.client;
import com.hbm.satellite.cargo.*;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.*;
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)public final class SatelliteCargoClient{
 @SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(SatelliteCargoContent.ENTITY.get(),SatelliteDockRenderer::new);event.registerEntityRenderer(SatelliteCargoContent.POD.get(),SatellitePodRenderer::new);}@SubscribeEvent public static void screens(RegisterMenuScreensEvent event){event.register(SatelliteCargoContent.MENU.get(),SatelliteDockScreen::new);}@SubscribeEvent public static void extensions(net.neoforged.neoforge.client.extensions.common.RegisterClientExtensionsEvent event){event.registerItem(new net.neoforged.neoforge.client.extensions.common.IClientItemExtensions(){private SatelliteDockItemRenderer renderer;@Override public net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer getCustomRenderer(){if(renderer==null)renderer=new SatelliteDockItemRenderer();return renderer;}},SatelliteCargoContent.ITEM.get());}private SatelliteCargoClient(){}
}
